import DateTimePicker, { DateTimePickerAndroid } from "@react-native-community/datetimepicker";
import { useState } from "react";
import { Platform, ScrollView, StyleSheet, Text, TextInput, View } from "react-native";
import MapView, { Marker, type LatLng } from "react-native-maps";
import { Button, FieldError, formatWhen, styles } from "./ui";

// Where the picker map opens when there's no point yet: the fictional town's
// reference point (seed data). Deliberately NOT derived from the member's
// home location, which this feature must never use (spec section 8).
const TOWN_CENTER = { latitude: 40.0, longitude: -100.0 };

export type MeetupFormValues = {
  title: string;
  startsAt: Date;
  placeName: string;
  point?: LatLng;
};

export type FormErrors = Record<string, string>;

/** Turn Zod / API issues into per-field messages for this form. */
export function issuesToErrors(issues: { path: string | PropertyKey[]; message: string }[]): FormErrors {
  const errors: FormErrors = {};
  for (const issue of issues) {
    const path = Array.isArray(issue.path) ? issue.path.join(".") : String(issue.path);
    if (path === "meetingPoint.lat" || path === "meetingPoint.lng") {
      errors["meetingPoint.point"] ??= "Tap the map to place the meeting point";
    } else {
      errors[path] ??= issue.message;
    }
  }
  return errors;
}

type Props = {
  initial: MeetupFormValues;
  submitLabel: string;
  busy: boolean;
  errors: FormErrors;
  formError?: string;
  onSubmit: (values: MeetupFormValues) => void;
};

export function MeetupForm({ initial, submitLabel, busy, errors, formError, onSubmit }: Props) {
  const [title, setTitle] = useState(initial.title);
  const [startsAt, setStartsAt] = useState(initial.startsAt);
  const [placeName, setPlaceName] = useState(initial.placeName);
  const [point, setPoint] = useState(initial.point);

  function pickAndroid(mode: "date" | "time") {
    DateTimePickerAndroid.open({
      value: startsAt,
      mode,
      minimumDate: mode === "date" ? new Date() : undefined,
      onValueChange: (_event, date) => setStartsAt(date),
    });
  }

  const center = point ?? TOWN_CENTER;

  return (
    <ScrollView style={styles.screen} contentContainerStyle={styles.pad} keyboardShouldPersistTaps="handled">
      <Text style={styles.label}>Title</Text>
      <TextInput style={styles.input} value={title} onChangeText={setTitle} maxLength={80} placeholder="Saturday morning loop" />
      <FieldError message={errors.title} />

      <Text style={styles.label}>Starts</Text>
      {Platform.OS === "android" ? (
        <View style={styles.row}>
          <Text style={styles.text}>{formatWhen(startsAt.toISOString())}</Text>
          <Button label="Date" variant="secondary" onPress={() => pickAndroid("date")} />
          <Button label="Time" variant="secondary" onPress={() => pickAndroid("time")} />
        </View>
      ) : (
        <DateTimePicker
          value={startsAt}
          mode="datetime"
          minimumDate={new Date()}
          onValueChange={(_event, date) => setStartsAt(date)}
        />
      )}
      <FieldError message={errors.startsAt} />

      <Text style={styles.label}>Meeting point name</Text>
      <TextInput
        style={styles.input}
        value={placeName}
        onChangeText={setPlaceName}
        maxLength={120}
        placeholder="Fountain plaza, Town Green"
      />
      <FieldError message={errors["meetingPoint.name"]} />

      <Text style={styles.label}>Meeting point (tap the map; use a public place)</Text>
      <MapView
        style={local.map}
        initialRegion={{ ...center, latitudeDelta: point ? 0.01 : 0.05, longitudeDelta: point ? 0.01 : 0.05 }}
        showsUserLocation={false}
        onPress={(e) => setPoint(e.nativeEvent.coordinate)}
      >
        {point && <Marker coordinate={point} />}
      </MapView>
      <Text style={styles.muted}>
        {point ? `${point.latitude.toFixed(6)}, ${point.longitude.toFixed(6)}` : "No point picked yet"}
      </Text>
      <FieldError message={errors["meetingPoint.point"]} />

      <FieldError message={formError} />
      <Button
        label={submitLabel}
        busy={busy}
        onPress={() => onSubmit({ title, startsAt, placeName, point })}
      />
    </ScrollView>
  );
}

const local = StyleSheet.create({
  map: { width: "100%", height: 240, borderRadius: 10 },
});

import { CreateMeetupInput } from "@altair/contracts";
import { router, useLocalSearchParams } from "expo-router";
import { useState } from "react";
import { MeetupForm, issuesToErrors, type FormErrors, type MeetupFormValues } from "@/components/MeetupForm";
import { ApiRequestError } from "@/lib/api";
import { useCreateMeetup } from "@/lib/queries";

function tomorrowAt8() {
  const d = new Date();
  d.setDate(d.getDate() + 1);
  d.setHours(8, 0, 0, 0);
  return d;
}

export default function CreateMeetup() {
  const { groupId } = useLocalSearchParams<{ groupId: string }>();
  const create = useCreateMeetup();
  const [errors, setErrors] = useState<FormErrors>({});
  const [formError, setFormError] = useState<string>();

  async function submit(v: MeetupFormValues) {
    setFormError(undefined);
    // Same schema the server validates with: catch mistakes before the
    // round trip. The server still re-validates (and checks membership).
    const parsed = CreateMeetupInput.safeParse({
      groupId,
      title: v.title,
      startsAt: v.startsAt.toISOString(),
      meetingPoint: { name: v.placeName, lat: v.point?.latitude, lng: v.point?.longitude },
    });
    if (!parsed.success) return setErrors(issuesToErrors(parsed.error.issues));
    setErrors({});

    try {
      const { id } = await create.mutateAsync(parsed.data);
      router.replace({ pathname: "/meetup/[id]", params: { id } });
    } catch (e) {
      // Show the server's answer, field by field where it gives one.
      if (e instanceof ApiRequestError) {
        setErrors(issuesToErrors(e.issues));
        setFormError(e.message);
      } else {
        setFormError("Something went wrong");
      }
    }
  }

  return (
    <MeetupForm
      initial={{ title: "", startsAt: tomorrowAt8(), placeName: "" }}
      submitLabel="Create meetup"
      busy={create.isPending}
      errors={errors}
      formError={formError}
      onSubmit={submit}
    />
  );
}

import { UpdateMeetupInput, type Meetup } from "@altair/contracts";
import { router, useLocalSearchParams } from "expo-router";
import { useState } from "react";
import { MeetupForm, issuesToErrors, type FormErrors, type MeetupFormValues } from "@/components/MeetupForm";
import { Empty, ErrorState, Loading } from "@/components/ui";
import { ApiRequestError } from "@/lib/api";
import { useMeetup, useUpdateMeetup } from "@/lib/queries";

// Bonus: creator-only edit. The server enforces creator-only and "not
// cancelled"; this screen just doesn't offer the form to anyone else.
export default function EditMeetup() {
  const { id } = useLocalSearchParams<{ id: string }>();
  const meetup = useMeetup(id);

  if (meetup.isPending) return <Loading />;
  if (meetup.isError) return <ErrorState message={meetup.error.message} onRetry={() => meetup.refetch()} />;
  const m = meetup.data;
  // The creator always gets the exact point, so this also covers "not yours".
  if (!m || !m.isCreator || m.meetingPoint.kind !== "exact") return <Empty title="You can't edit this meetup" />;
  if (m.status === "cancelled") return <Empty title="A cancelled meetup can't be edited" />;

  return <EditForm meetup={m} />;
}

function EditForm({ meetup }: { meetup: Meetup }) {
  const update = useUpdateMeetup(meetup.id);
  const [errors, setErrors] = useState<FormErrors>({});
  const [formError, setFormError] = useState<string>();
  const point = meetup.meetingPoint.kind === "exact" ? meetup.meetingPoint : undefined;

  async function submit(v: MeetupFormValues) {
    setFormError(undefined);

    // Send only what changed. An unchanged start time is left out, so the
    // future-start rule applies only when the time actually moves.
    const startsAt = v.startsAt.toISOString();
    const pointChanged =
      v.placeName !== point?.name || v.point?.latitude !== point?.lat || v.point?.longitude !== point?.lng;
    const parsed = UpdateMeetupInput.safeParse({
      title: v.title !== meetup.title ? v.title : undefined,
      startsAt: Date.parse(startsAt) !== Date.parse(meetup.startsAt) ? startsAt : undefined,
      meetingPoint: pointChanged
        ? { name: v.placeName, lat: v.point?.latitude, lng: v.point?.longitude }
        : undefined,
    });
    if (!parsed.success) {
      setErrors(issuesToErrors(parsed.error.issues));
      if (parsed.error.issues.some((i) => i.path.length === 0)) setFormError("Nothing changed");
      return;
    }
    setErrors({});

    try {
      await update.mutateAsync(parsed.data);
      router.back();
    } catch (e) {
      if (e instanceof ApiRequestError) {
        setErrors(issuesToErrors(e.issues));
        setFormError(e.message);
      } else {
        setFormError("Something went wrong");
      }
    }
  }

  return (
    <MeetupForm
      initial={{
        title: meetup.title,
        startsAt: new Date(meetup.startsAt),
        placeName: point?.name ?? "",
        point: point && { latitude: point.lat, longitude: point.lng },
      }}
      submitLabel="Save changes"
      busy={update.isPending}
      errors={errors}
      formError={formError}
      onSubmit={submit}
    />
  );
}

